export function findMapRecord(name: string): ValorantMapRecord | undefined {
  if (!name) return undefined;
  const key = name.toLowerCase();
  return (
    VALORANT_MAPS.find((m) => m.key === key) ||
    VALORANT_MAPS.find((m) => key.includes(m.key)) ||
    VALORANT_MAPS.find((m) => m.key.includes(key))
  );
}

/** Convert in-game world coords (Unreal Units) to a 0..1 fraction of the minimap. */
export function worldToMinimap(
  worldX: number,
  worldY: number,
  map: ValorantMapRecord,
): { x: number; y: number } {
  // API coordinates are cross-mapped: worldY drives minimapX via xMultiplier/xScalar,
  // and worldX drives minimapY via yMultiplier/yScalar.
  return {
    x: worldY * map.xMultiplier + map.xScalarToAdd,
    y: worldX * map.yMultiplier + map.yScalarToAdd,
  };
}
